const l = (t) => String(t || '').split(',').map(s => s.trim()).filter(Boolean);
const dias = l(vars.dias), tmax = l(vars.tmax).map(Number), tmin = l(vars.tmin).map(Number), lluvia = l(vars.lluvia).map(Number);
if (!dias.length) return 'Sin datos: ejecuta el flow';
const nom = (iso) => ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'][new Date(iso + 'T12:00:00').getDay()];
return `${vars.ciudad} · próximos ${dias.length} días\n` + dias.map((d, i) => `${nom(d)} ${d.slice(8)}/${d.slice(5, 7)}   ${tmax[i].toFixed(1).padStart(5)}° / ${tmin[i].toFixed(1).padStart(5)}°   ${lluvia[i] > 0 ? '☔ ' + lluvia[i] + ' mm' : '☀️'}`).join('\n');

// Botones que CAMBIAN el flow: cada ciudad escribe latitud/longitud en Variables (por el MCP) y relanza el flow.
if (typeof document === 'undefined') return 'CLI: sin interfaz';
const ID = 'flow-botonera-tiempo';
document.getElementById(ID)?.remove(); // se recrea en cada Run Flow con la ciudad y el resumen nuevos
const CIUDADES = [['Madrid', 40.42, -3.70], ['Barcelona', 41.39, 2.17], ['Sevilla', 37.39, -5.99], ['Bilbao', 43.26, -2.93], ['Tenerife', 28.47, -16.25]];
const host = document.createElement('div'); host.id = ID; document.body.append(host);
const root = host.attachShadow({ mode: 'open' });
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
root.innerHTML = `<style>
  :host{all:initial;font:13px system-ui,sans-serif;color:#e2e8f0}
  .box{position:fixed;right:16px;top:72px;z-index:50;background:#0f172a;border:1px solid #334155;border-radius:12px;padding:10px 12px;box-shadow:0 8px 30px #0008;max-width:min(520px,calc(100vw - 32px))}
  .bar{display:flex;gap:6px;align-items:center;flex-wrap:wrap} .bar b{color:#34d399;margin-right:4px} .bar span{color:#94a3b8}
  button{font:inherit;color:#e2e8f0;background:#1e293b;border:1px solid #475569;border-radius:8px;padding:5px 9px;cursor:pointer}
  button:hover{background:#334155} button.on{background:#34d399;color:#0b1220;border-color:#34d399} button:disabled{opacity:.5;cursor:default} button.x{background:transparent;border-color:transparent;color:#94a3b8}
  pre{margin:10px 0 0;font:12px/1.5 ui-monospace,monospace;color:#cbd5e1;white-space:pre-wrap}
</style>
<div class="box"><div class="bar"><b>🌤 ${esc(vars.ciudad || '?')}</b>${CIUDADES.map(([c]) => `<button data-c="${esc(c)}"${c === vars.ciudad ? ' class="on"' : ''}>${esc(c)}</button>`).join('')}<button id="run" title="Volver a ejecutar">▶</button><button id="x" class="x" title="Quitar (el próximo Run Flow lo vuelve a dibujar)">✕</button><span id="estado"></span></div>
<pre>${esc(vars.resumenTiempo || 'Ejecuta el flow para ver la previsión')}</pre></div>`;
const $ = (s) => root.querySelector(s), estado = (t) => { $('#estado').textContent = t; };
const bloquear = (v) => root.querySelectorAll('button:not(#x)').forEach(b => { b.disabled = v; }); // ✕ siempre disponible
const mcp = async (name, args) => { const r = await fetch('/mcp', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' }, body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: 'tools/call', params: { name, arguments: args || {} } }) }); if (r.status === 401) throw new Error('el MCP pide token (FLOW_MCP_TOKEN)'); const j = await r.json(); if (j.error) throw new Error(j.error.message); if (j.result?.isError) throw new Error(j.result.content?.[0]?.text || name); return j.result; };
root.querySelectorAll('[data-c]').forEach(b => { b.onclick = async () => { const [c, lat, lon] = CIUDADES.find(x => x[0] === b.dataset.c); bloquear(true); estado(`Cambiando a ${c} y ejecutando…`); try { await mcp('variables_set', { variables: { ciudad: c, latitud: String(lat), longitud: String(lon) } }); await mcp('flow_run', {}); } catch (e) { estado('Error: ' + e.message); bloquear(false); } }; });
$('#run').onclick = async () => { bloquear(true); estado('Ejecutando…'); try { await mcp('flow_run', {}); } catch (e) { estado('Error: ' + e.message); bloquear(false); } };
$('#x').onclick = () => host.remove();
return `Botonera dibujada · ${vars.ciudad} · ${new Date().toLocaleTimeString('es-ES')}`;
